fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Preallocate a vector with the combined capacity of v1 and v2
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Copy all elements from v1
    result.extend_from_slice(&v1[..]);
    // Copy all elements from v2
    result.extend_from_slice(&v2[..]);
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // Ensure `first` is non-empty
    assert!(!first.is_empty(), "`first` must have at least one element");
    // Compute how many elements to take from `first` (all but the last)
    let take = first.len() - 1;
    // Preallocate for (first.len() - 1) + second.len()
    let mut result = Vec::with_capacity(take + second.len());
    // Copy the prefix of `first` (excluding its last element)
    result.extend_from_slice(&first[..take]);
    // Append all of `second`
    result.extend_from_slice(&second[..]);
    result
}